7.script:
// Pulse-arc welder controller: key, charge, pre-flow, arm, fire on lift, post-flow.

fn fmt1(x) {
    let t = (x * 10.0).round().to_int();
    `${t / 10}.${t % 10}`
}

fn volts_for(e, c_f, v_arc) {
    (2.0 * e / c_f + v_arc * v_arc).sqrt()
}

// Log-taper knob: 0..3300 mV -> e_min..e_max joules in 0.1 J steps.
fn knob_joules(mv, e_min, e_max) {
    let x = mv.to_float() / 3300.0;
    if x < 0.0 { x = 0.0; }
    if x > 1.0 { x = 1.0; }
    let e = e_min * ((e_max / e_min).ln() * x).exp();
    (e * 10.0).round() / 10.0
}

fn set_outputs(st) {
    if st == "CHARGE" { charger.on(); } else { charger.off(); }
    if st == "PREFLOW" || st == "ARMED" || st == "POST" { argon.on(); } else { argon.off(); }
    if st == "ARMED" { armed.on(); } else { armed.off(); }
}

fn state_color(st) {
    switch st {
        "SAFE" => [40, 60, 140],
        "CHARGE" => [200, 140, 0],
        "READY" => [0, 170, 70],
        "HIGH" => [130, 60, 170],
        "PREFLOW" | "POST" => [0, 130, 170],
        "ARMED" => [220, 30, 30],
        "STUCK" => [220, 100, 0],
        _ => [220, 0, 0]
    }
}

fn hint(st, fault) {
    switch st {
        "SAFE" => "turn arm key on",
        "CHARGE" => "charging bank...",
        "READY" => "hold pedal to arm",
        "HIGH" => "bleeding down...",
        "PREFLOW" => "argon pre-flow",
        "ARMED" => "touch, then lift",
        "POST" => "argon post-flow",
        "STUCK" => "lift tip, resharpen",
        "FAULT" => fault,
        _ => ""
    }
}

fn paint_line(y, text, r, g, b) {
    lcd_rect(0, y - 2, 128, 13, 6, 8, 16);
    lcd_text(4, y, text, r, g, b);
}

fn paint_state(st, fault) {
    let c = state_color(st);
    lcd_rect(0, 0, 128, 16, c[0], c[1], c[2]);
    lcd_text(4, 4, "PULSE ARC", 255, 255, 255);
    lcd_text(124 - st.len * 6, 4, st, 255, 255, 255);
    lcd_rect(0, 108, 128, 20, 16, 18, 30);
    lcd_text(4, 113, hint(st, fault), 225, 225, 235);
}

fn on_start() {
    this.k = #{
        c_f: 0.0141,             // bank capacitance, farads
        v_arc: 12.0,             // bank volts where the arc goes out
        v_trip: 64.0,            // over-voltage fault, volts
        div: 21.0,               // bank divider ratio, 200k over 10k
        e_min: 1.0,
        e_max: 23.0,
        tol: 0.8,                // ready window around the target, volts
        preflow_ms: 400,
        postflow_ms: 1200,
        arm_timeout_ms: 8000,
        stuck_ms: 3000,
        charge_timeout_ms: 30000
    };
    this.st = "BOOT";
    this.t_state = millis();
    this.fault = "";
    this.welds = 0;
    this.e_set = -1.0;
    this.v_tgt = 0.0;
    this.knob_mv = -1000;
    this.v_shown = -100.0;
    this.t_paint = 0;
    this.ped_prev = false;
    this.tip_prev = false;
    this.touched = false;
    this.t_touch = 0;
    this.blink = false;
    this.t_blink = 0;
    set_outputs("SAFE");
    lcd_init(7, 2, 25, 26, 3);
    lcd_clear(6, 8, 16);
    paint_line(74, "WELDS 0", 200, 200, 210);
    paint_line(90, `C ${fmt1(this.k.c_f * 1000.0)} mF  trip ${fmt1(this.k.v_trip)} V`, 110, 120, 150);
    log("arm_key on, set energy, drag bank_sense to TGT, hold pedal, press then release tip_contact");
}

fn on_tick(dt_ms) {
    // Skip ticks until on_start has run.
    if this.st == () { return; }
    let k = this.k;
    let now = millis();

    let key = arm_key.is_on();
    let ped = pedal.is_pressed();
    let ped_edge = ped && !this.ped_prev;
    this.ped_prev = ped;
    let tip = tip_contact.is_pressed();
    let tip_down = tip && !this.tip_prev;
    let tip_up = !tip && this.tip_prev;
    this.tip_prev = tip;

    let mv = energy.millivolts();
    if (mv - this.knob_mv).abs() > 12 {
        this.knob_mv = mv;
        let e = knob_joules(mv, k.e_min, k.e_max);
        if e != this.e_set {
            this.e_set = e;
            this.v_tgt = volts_for(e, k.c_f, k.v_arc);
            this.v_shown = -100.0;
            paint_line(26, `SET   ${fmt1(e)} J`, 255, 220, 90);
            paint_line(42, `TGT   ${fmt1(this.v_tgt)} V`, 170, 190, 255);
        }
    }
    let v_tgt = this.v_tgt;
    let v_bank = bank_sense.millivolts().to_float() / 1000.0 * k.div;

    let st = this.st;
    let next = st;
    let fired = false;
    let beep_ms = 0;
    let age = now - this.t_state;
    if !key {
        next = "SAFE";
    } else if v_bank > k.v_trip {
        next = "FAULT";
        this.fault = "OVERVOLTAGE";
    } else {
        switch st {
            "BOOT" | "SAFE" => { next = "CHARGE"; },
            "CHARGE" => {
                if v_bank >= v_tgt {
                    next = "READY";
                } else if age > k.charge_timeout_ms {
                    next = "FAULT";
                    this.fault = "CHARGE TIMEOUT";
                }
            },
            "READY" => {
                if v_bank < v_tgt - k.tol {
                    next = "CHARGE";
                } else if v_bank > v_tgt + k.tol {
                    next = "HIGH";
                } else if ped_edge {
                    next = "PREFLOW";
                }
            },
            "HIGH" => {
                if v_bank <= v_tgt + k.tol / 2.0 { next = "READY"; }
            },
            "PREFLOW" => {
                if !ped {
                    next = "POST";
                } else if age >= k.preflow_ms {
                    next = "ARMED";
                }
            },
            "ARMED" => {
                if !ped {
                    next = "POST";
                } else if tip_down {
                    this.touched = true;
                    this.t_touch = now;
                } else if tip_up && this.touched {
                    next = "POST";
                    fired = true;
                } else if tip && this.touched && now - this.t_touch > k.stuck_ms {
                    next = "STUCK";
                } else if !tip && age > k.arm_timeout_ms {
                    next = "POST";
                }
            },
            "POST" => {
                if age >= k.postflow_ms { next = "CHARGE"; }
            },
            "STUCK" => {
                if !tip { next = "CHARGE"; }
            },
            _ => {}
        }
    }

    if next != st {
        this.st = next;
        this.t_state = now;
        if next == "ARMED" {
            this.touched = tip;
            this.t_touch = now;
        }
        if next == "SAFE" { this.fault = ""; }
        set_outputs(next);
        let c = state_color(next);
        rgb(c[0] / 4, c[1] / 4, c[2] / 4);
        paint_state(next, this.fault);
        if fired {
            this.welds += 1;
            beep_ms = 60;
            paint_line(74, `WELDS ${this.welds}`, 200, 200, 210);
            log(`weld #${this.welds}: ${fmt1(this.e_set)} J at ${fmt1(v_bank)} V`);
        }
        if next == "STUCK" {
            beep_ms = 400;
            log("tip held on the work while armed: disarmed");
        }
        if next == "FAULT" {
            beep_ms = 800;
            log(`FAULT: ${this.fault}`);
        }
        log(`${st} -> ${next}`);
    }

    if (v_bank - this.v_shown).abs() >= 0.3 && now - this.t_paint >= 200 {
        this.v_shown = v_bank;
        this.t_paint = now;
        let c = if v_bank < v_tgt - k.tol {
            [255, 170, 40]
        } else if v_bank > v_tgt + k.tol {
            [200, 120, 255]
        } else {
            [90, 230, 120]
        };
        paint_line(58, `BANK  ${fmt1(v_bank)} V`, c[0], c[1], c[2]);
    }

    if this.st == "FAULT" && now - this.t_blink >= 300 {
        this.t_blink = now;
        this.blink = !this.blink;
        if this.blink { rgb(55, 0, 0); } else { rgb(0, 0, 0); }
    }

    // Beep after every other action this tick.
    if beep_ms > 0 { beeper.beep(beep_ms); }
}
